       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"183dd67e-32e0-555d-92eb-6b5173a73112","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -أرض زراعية مثبت ملكيتها باإلعام الصادر من المحكمة العامة واملصدق من محكمة التمييز -اعتراض أمانة منطقة املدينة املنورة على اإلعام السابق -املطالبة برفع يد املدعى عن األرض محل الدعوى وتسليمها إلى املختص للتصرف فيها- سقوط دعوى اجلهة املدعية ،وردها ،وإخاء سبيل املدعى عليه من","document_number":"34314925","case_number":"32453097","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/8","year":"1434","subject":"عقار -أرض زراعية مثبت ملكيتها باإلعام الصادر من المحكمة العامة واملصدق من محكمة التمييز -اعتراض أمانة منطقة املدينة املنورة على اإلعام السابق -املطالبة برفع يد املدعى عن األرض محل الدعوى وتسليمها إلى املختص للتصرف فيها- سقوط دعوى اجلهة املدعية ،وردها ،وإخاء سبيل املدعى عليه من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34314925 :‬تاريخه ‪1434/9/8 :‬هـ‬\n                  ‫رقم الدعوى ‪32453097 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34349149‬تاريخه‪1434/11/4 :‬هـ‬\n\n\n‫عقــار‪ -‬أرض زراعيــة مثبــت ملكيتهــا باإلعــام الصــادر مــن احملكمــة‬\n‫العامــة واملصــدق مــن محكمــة التمييــز‪ -‬اعتــراض أمانــة منطقــة‬\n‫املدينــة املنــورة علــى اإلعــام الســابق‪ -‬املطالبــة برفــع يــد املدعــى عــن‬\n‫األرض محــل الدعــوى وتســليمها إلــى املختــص للتصــرف فيهــا‪-‬‬\n‫ســقوط دعــوى اجلهــة املدعيــة‪ ،‬وردهــا‪ ،‬وإخــاء ســبيل املدعــى عليــه مــن‬\n                                                              ‫هــذه الدعــوى ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا جــاء يف فتــاوى ســماحة مفتــي الديــار الســعودية الشــيخ محمــد‬\n‫بــن إبراهيــم (‪( )139/8‬مــن أحيــاء أرض ـ ًا أحيــاء شــرعي ًا وثبــت متلكــه‬\n‫لهــا فــا يضــر بعــد ذلــك صيرورتهــا مواتــا مــادام يعــرف مالكهــا فهــي‬\n                                                        ‫مــوات لغــة ال شــرع ًا )‬\n                                        ‫‪ -2‬قاعدة االجتهاد ال ينقض مبثله‬\n\n\n\n‫ادعــى منــدوب أمانــة منطقــة املدينــة املنــورة بــأن للمدعــى عليــه أرضــا‬\n‫زراعيــة مثبــت متلكــه لهــا مبوجــب األعــام الصــادر مــن محكمــة‬\n‫محافظــة احلناكيــة ( التابعــة ملنطقــة املدينــة املنــورة ) وذكــر رقمــه‬\n‫وتاريخــه وأنــه مت تصديقــه مــن محكمــة التمييــز‪ -‬قــرر املدعــى وكالــة‬\n\n                                                                                     ‫‪500‬‬\n\f      ‫بــأن موكلتــه األمانــة غيــر قانعــه بهــذا اإلعــام ألســباب منهــا أنــه ورد‬\n      ‫يف األعــام أن املوقــع يحتــوي علــى نخــل وأثــل وبئــر ارتوازيــة وثالثــة آبــار‬\n      ‫عاديــة ومعقمــة مــن جميــع اجلهــات بســلك شــائك وبهــا خزانــات بينمــا‬\n      ‫يف احلقيقــة ال يوجــد شــيء ممــا ذكــر ســوى أثــار جــذوع نخــل فقــط‬\n      ‫وبئــر قدميــة بعمــق ثالثــة أمتــار ال يوجــد فيهــا مــاء وكــوم طــن يدعــى‬\n      ‫املدعــى عليــه أنهــا منــازل قدميــة كمــا يوجــد بئريــن وهــذا األحيــاء ال‬\n      ‫ميكــن أن يغطــى املســاحة الكبيــرة الــواردة يف األعــام كمــا أن املوقــع‬\n      ‫خــارج النطــاق العمرانــي‪ -‬وعليــه فــإن األعــام املذكــور صــدر مخالفـ ًا‬\n      ‫لألوامــر الســامية وأن موكلتــه تقدمــت باعتــراض لــدى احملكمــة‬\n      ‫وذكــرت األوامــر الســامية التــي متنــع التملــك اال أن القاضــي صــرف‬\n      ‫النظــر عــن املعارضــة وصــدق احلكــم مــن مرجعــه‪ -‬طلب املدعــى وكالة‬\n      ‫احلكــم علــى املدعــى عليــه برفــع يــده عــن هــذ األرض محــل الدعــوى‬\n      ‫وإلغــاء األعــام املذكــور وتســليم األرض ألمانــة منطقــة املدينــة املنــورة‬\n      ‫للتصــرف فيــه بحكــم االختصــاص‪ -‬أجــاب املدعــى عليــه بصحــة مــا‬\n      ‫جــاء يف الدعــوى وأنكــر أن األحيــاء ال ميكــن أن يغطي املســاحة الواردة‬\n      ‫يف االعــام وذكــر بــأن احيــاء األرض قبــل صــدور جميــع أومــر املنــع‬\n      ‫حســب مــا يتضــح مــن صــورة األعــام وأن املوقــع داخــل النطــاق العمراني‬\n      ‫حســب مــا يتضــح مــن املصــور اجلــوي‪ -‬جــرى االستفســار عــن صــك حجــة‬\n      ‫االســتحكام وهــو مطابــق لســجله وســاري املفعــول‪ -‬مبــا أن صــك‬\n      ‫حجــة االســتحكام محــل الدعــوى مســتكمل لإلجــراءات الشــرعية‬\n      ‫والنظاميــة وأن دعــوى اجلهــة املدعيــة برمتهــا هــي بعينهــا مــا ســبق أن‬\n      ‫تقدمــت بــه مــن اعتــراض عنــد اســتخراج صــك حجــه االســتحكام‪-‬‬\n      ‫وألن مــن أحيــا أرضــا أحيــاء شــرعي ًا وثبــت متلكــه فــا يضــر بعــد ذلــك‬\n\n\n‫‪501‬‬\n\f‫صيرورتهــا موات ـاً‪ -‬وألن االجتهــاد ال ينقــض مبثلــه‪ -‬لــذا صــدر احلكــم‬\n‫بســقوط دعــوى اجلهــة املدعيــة وردهــا وإخــاء ســبيل املدعــى عليــه مــن‬\n‫هــذه الدعــوى‪ -‬اعتــرض املدعــى وكالــة‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                ‫االســتئناف ‪.‬‬\n\n\n\n‫أمــا بعــد‪:‬‬\n           ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬            ‫الصــاة و َّ‬  ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫العامــة يف املدينــة املنـ َّـورة‪ ،‬القائــم‬         ‫ـدي أنــا ‪ ...‬القاضــي باحملكمــة َّ‬               ‫فلـ َّ‬\n‫الشــيخ ‪ ،...‬القاضــي يف احملكمــة نفســها‪ .‬حضــر املواطــن‬                              ‫بعمــل فضيلــة َّ‬\n‫املدني رقم (‪ ،)...‬بصف ِت ِه مكل ًَّفا‬     ‫ِّ‬           ‫الســجلِّ‬     ‫ـعودي اجلنسـ َّـي ِة مبوجب ِّ‬\n                                                                                                 ‫‪ُ ،...‬سـ ُّ‬\n‫مــن «أمانــة منطقــة املدينــة املنـ َّـورة»‪ ،‬مبوجــب اخلطــاب رقــم (‪ )76831‬يف‬\n‫واملقيد بأساس هذه احملكمة برقم (‪)332270947‬‬                                    ‫َّ‬       ‫‪1433/12/26‬هـ‪،‬‬\n‫ـعودي‬\n  ‫يف ‪1433/12/28‬هــ‪ ،‬وا َّدعــى علــى احلاضــر معــه املواطــن‪ُ ،... /‬سـ ِّ‬\n‫إن لــدى‬ ‫الســجلِّ املدنـ ِّـي رقــم (‪ .)...‬قائـ ًـا يف دعــواه‪َّ :‬‬                 ‫اجلنسـ َّـي ِة مبوجــب ِّ‬\n‫زراعيـ ًة‪ُ ،‬مثبت ًا مت ُّلكــه لها‪ ،‬مبوجب‬       ‫َّ‬           ‫أرضا‬ ‫املدعــى عليــه ـ ـ هــذا احلاضــر ـ ـ ً‬    ‫َّ‬\n‫احلناكيــة رقــم (‪)103‬‬‫َّ‬          ‫العامــة مبحافظــة‬      ‫َّ‬           ‫الصــادر مــن احملكمــة‬ ‫اإلعــام َّ‬\n‫يف ‪1408/11/29‬هــ‪ ،‬و املصـ َّـدق مــن محكمــة ال َّتم ِييــز بالقــرار رقــم‬\n‫موكلتــي غيــر قانع ـ ٍة بهــذا‬      ‫ِّ‬            ‫(‪ )10/2/1609‬يف ‪1410/05/01‬هــ‪ ،‬و‬\n‫أن املوقــع‬  ‫اإلعــام؛ لألســباب ال َّتاليــة‪َّ ،‬أو ًل‪ :‬ورد يف اإلعــام ـ ـ املذكــور ـ ـ َّ‬\n‫ارتوازي ـةٍ‪ ،‬و ثالثــة آبــا ٍر عادي ـةٍ‪ ،‬و‬  ‫َّ‬              ‫يحتــوي علــى نخـ ٍـل‪ ،‬و أثـ ٍـل‪ ،‬و بئـ ٍـر‬\n‫ـائك‪ ،‬و بــه ثــاث (‪)3‬‬    ‫ـلك شـ ٍ‬      ‫معقم ـ ٍة مــن جميــع اجلهــات‪ ،‬و محاط ـ ٍة بسـ ٍ‬                  ‫َّ‬\n‫ك َر‪،‬‬  ‫مما ُذ ِ‬ ‫ـيء َّ‬\n                     ‫حاليــا ـ ـ يف احلقيقــة ـ ـ ال يوجد شـ ٌ‬             ‫خزانــات مــاء‪ ،‬بينمــا هــو ًّ‬       ‫َّ‬\n‫ســوى آثــار جــذوع نخـ ٍـل فقــط‪ ،‬و بئـ ٍـر قدمي ـ ٍة بعمــق ثالثــة (‪ )3‬أمتــا ٍر‬\n\n                                                                                                                      ‫‪502‬‬\n\f      ‫املدعــى عليــه أ َّنهــا‬\n                           ‫يدعــي َّ‬\n                                  ‫ن َّ‬\n                                     ‫ـاء‪ ،‬و كــوم ط ـ ٍ‬\n                                                    ‫تقريبــا‪ ،‬و ال يوجــد فيهــا مـ ٌ‬\n                                                                                ‫ً‬\n      ‫كانــت منــازل قدميـ ًة‪ ،‬كمــا يوجــد بئريــن‪ ،‬و هــذا اإلحيــاء ال ميكــن أن‬\n      ‫يغطــي مســاح ًة تصــل إلــى ســتمائ ٍة و عشــرة آالف (‪ )610,000‬متـ ٍـر‬     ‫ِّ‬\n      ‫الســامي رقــم‬    ‫خالفــا لألمــر َّ‬   ‫ـإن ا ُحلكــم صــدر ُم ً‬                ‫مربـ ٍـع‪ ،‬و بذلــك فـ َّ‬     ‫َّ‬\n      ‫املتضمــن‪« :‬بأنــه ال يجــوز إخــراج‬         ‫ِّ‬        ‫(‪/1950‬م) يف ‪1404/06/13‬هــ‪ ،‬و‬\n      ‫ثانيــا‪ :‬ســبق‬  ‫مت إحيــاؤه فقــط مــن األراضــي»‪ً .‬‬                     ‫ـوك َّإل علــى مــا َّ‬\n                                                                                                    ‫صكـ ٍ‬\n       ‫حجــة االســتحكام علــى األرض ـ ـ محــلُّ‬                ‫ملوكلتــي املعارضــة علــى طلــب َّ‬        ‫ِّ‬\n      ‫الدعــوى ـ ـ مبوجــب اخلطــاب رقــم (‪ )5910/3481‬يف ‪1401/11/22‬هــ‪،‬‬                                              ‫َّ‬\n      ‫الســامية ا َّلتــي متنــع ال َّتم ُّلــك‪ ،‬و أ َّنــه يجــب‬\n                                                              ‫املتضمــن‪ :‬اإلشــارة إلــى األوامــر َّ‬   ‫ِّ‬\n      ‫األخــذ بهــا بعــن االعتبــار‪ ،‬و لكـ َّـن فضيلــة القاضــي لــم ينظــر إلــى ذلــك‬\n      ‫بعــن االعتبــار‪ ،‬و صــرف ال َّنظــر عــن املعارضــة‪ ،‬و صــدق ا ُحلكــم مــن‬\n      ‫تؤكــد علــى معارضتهــا حيــال‬          ‫موكلتــي ـ ـ األمانــة ـ ـ مــا زالــت ِّ‬    ‫مرجعــه‪ ،‬و ِّ‬\n      ‫أن املوقــع خــارج ال ِّنطــاق العمرانــي‬            ‫صــدور ا ُحلكــم بال َّتم ُّلــك‪ .‬ثال ًثــا‪َّ :‬‬\n      ‫الصويــدرة َّإل جــزء ًا بســيط ًا منــه؛ و بذلــك يتعـ َّـذر علــى األمانــة‬            ‫حملافظــة ُّ‬\n      ‫موكلتــي ـ ـ األمانــة ـ ـ‬‫ِّ‬       ‫حتقيــق الطلــب ـ ـ املذكــور ــ‪ ،‬باإلضافــة إلــى أن‬\n      ‫أن‬ ‫رابعــا‪َّ :‬‬\n                ‫للمدعــى عليــه بإثبــات ال َّتم ُّلــك‪ً .‬‬        ‫الصــادر َّ‬     ‫غيــر قانع ـ ٍة باحلكــم َّ‬\n      ‫آالف و مائتــن و خمســن‬           ‫مســاحة املوقــع تصــل إلــى س ـ ِّتمائ ٍة و عشــرة ٍ‬\n      ‫املربــع (‪،)610,250/28‬‬          ‫مرب ًعــا و ثمانيـ ًة و عشــرين باملائــة مــن املتر َّ‬        ‫متـ ًـرا َّ‬\n      ‫الشاســعة؛ و بذلك‬      ‫غطي تلك املســاحات َّ‬                  ‫أن اإلحياء ـ املشــار إليها ـ ال ُت ِّ‬      ‫و َّ‬\n      ‫الســامي رقــم (‪ )19774‬يف‬                  ‫خالفــا لألمــر َّ‬        ‫ـإن ا ُحلكــم صــدر ُم ً‬           ‫فـ َّ‬\n      ‫‪1402/08/17‬هــ‪ ،‬املُب َّلــغ بال َّتعميــم رقم (‪ )5/269‬يف ‪1402/10/18‬هـ‪،‬‬\n      ‫«أن‬  ‫املتضمــن‪َّ :‬‬\n                   ‫ِّ‬          ‫الســامي رقــم (‪ )1492‬يف ‪1404/05/13‬هــ‪،‬‬                           ‫و األمــر َّ‬\n      ‫ـوك علــى األراضــي البيضــاء‬             ‫علــى احملكمــة عــدم إصــدار أي صكـ ٍ‬\n\n\n‫‪503‬‬\n\f‫أن‬‫الســامي»‪ ،‬كمــا َّ‬       ‫ـاحات شاســع ٍة َّإل بعــد االســتئذان مــن املقــام َّ‬        ‫مبسـ ٍ‬\n‫ـاء علــى ذلــك‬    ‫ـادي؛ و بنـ ً‬  ‫القصــد مــن ذلــك هــو املتاجــرة‪ ،‬و ال َّتكســب املـ ُّ‬\n‫مخالفــا ألوامــر ولـ ِّـي األمــر ا َّلــذي جتــب طاعتــه‪ ،‬و‬        ‫ً‬          ‫فــإن ا ُحلكــم صــدر‬\n‫للمدعــي و أمثالــه مبخالفــة ولــي األمــر‪ ،‬و عليــه‬                     ‫َّ‬        ‫ـجيعا‬\n                                                                                     ‫ُيعتبــر تشـ ً‬\n‫فموكلتــي ـ ـ أمانــة منطقــة املدينــة املنـ َّـورة ـ ـ تطلــب ســؤاله عــن هــذه‬               ‫ِّ‬\n‫الدعــوى ـ ـ‬  ‫الدعــوى‪ ،‬و ا ُحلكــم عليــه برفــع يــده عــن هــذه األرض ـ ـ محــلِّ َّ‬                     ‫َّ‬\n‫ملوكلتي ـ أمانة منطقة‬           ‫و ا ُحلكــم بإلغــاء اإلعــام ـ ـ املذكــور ـ و تســليمه ِّ‬\n‫املدينــة املنـ َّـورة ــ؛ لتتصـ َّـرف فيــه بحكــم االختصــاص‪ ،‬هــذه دعــواي‪ .‬و‬\n‫الدعــوى‪ ،‬أجــاب بقولــه‪ :‬مــا ذكــره‬                   ‫املدعــى عليــه عــن هــذا َّ‬    ‫بســؤال َّ‬\n‫املدعــي وكال ـ ًة يف دعــواه منــه مــا هــو صحيـ ٌـح‪ ،‬و منــه مــا هــو غيــر‬                          ‫َّ‬\n‫راعيـ ًة‬\n    ‫الز َّ‬  ‫ـدي األرض ِّ‬      ‫الصحيــح‪ :‬فهــو مــا ذكــره مــن أ َّنــه لـ َّ‬    ‫فأمــا َّ‬\n                                                                                       ‫صحيـ ٍـح‪َّ ،‬‬\n‫تغيــرت‬ ‫املثبــت مت ُّلكــي لهــا مبوجــب اإلعــام ـ ـ املشــار إليــه ــ‪ ،‬و أ َّنهــا قــد َّ‬\n‫ممــا ُذكــر‬    ‫ـيء َّ‬\n                    ‫ـور يف اإلعــام‪ ،‬إذ ال يوجــد بهــا اآلن شـ ٌ‬              ‫عــن مــا هــو مذكـ ٌ‬\n‫ســوى آثــار جــذوع نخـ ٍـل فقــط‪ ،‬و بئـ ٍـر قدمي ـ ٍة بعمــق ثالثــة (‪ )3‬أمتــا ٍر‬\n‫ن‪ ،‬و بئريــن‪ ،‬و‬        ‫ـاء‪ ،‬و يوجــد فيهــا كــوم ط ـ ٍ‬         ‫تقريبــا‪ ،‬و ال يوجــد فيهــا مـ ٌ‬   ‫ً‬\n‫حجــة‬ ‫أ َّنــه ســبق ألمانــة منطقــة املدينــة املنـ َّـورة املعارضــة علــى طلــب َّ‬\n‫الدعــوى ـ ـ مبوجــب اخلطــاب ـ ـ املشــار‬            ‫االســتحكام علــى األرض ـ ـ محــلُّ َّ‬\n‫أن فضيلــة القاضــي لــم ينظــر إلــى ذلــك بعــن االعتبــار‪ ،‬و صرف‬                         ‫إليــه ـ ـ و َّ‬\n‫الصحيح‬    ‫أما غيــر َّ‬   ‫ال َّنظــر عــن املعارضــة‪ ،‬و صــدق ا ُحلكــم مــن مرجعــه‪ .‬و َّ‬\n‫أن هــذا اإلحيــاء ال ميكــن أن‬                 ‫املدعــي وكال ـ ًة‪ ،‬مــن َّ‬  ‫فهــو‪ :‬مــا ذكــره َّ‬\n‫يغطــي مســاحة تصــل إلــى س ـ ِّتمائ ٍة و عشــرة آالف (‪ )610,000‬متــر‬                                ‫ِّ‬\n‫الســامي رقــم‬\n            ‫خالفــا لألمــر َّ‬\n                           ‫ـإن ا ُحلكــم صــدر ُم ً‬\n                                                ‫مربـ ٍـع‪ ،‬و بذلــك فـ َّ‬\n                                                                     ‫َّ‬\n‫املتضمــن‪« :‬بأنــه ال يجــوز إخــراج‬\n                              ‫ِّ‬     ‫(‪/1950‬م) يف ‪1404/06/13‬هــ‪ ،‬و‬\n\n\n                                                                                                                 ‫‪504‬‬\n\f      ‫وأن املوقــع خــارج‬        ‫مت إحيــاؤه فقــط مــن األراضــي»‪َّ .‬‬                     ‫ـوك َّإل علــى مــا َّ‬   ‫صكـ ٍ‬\n      ‫ـيطا منــه؛ و بذلــك‬            ‫«الصويــدرة» َّإل جــزء ًا بسـ ً‬       ‫ال ِّنطــاق العمرانــي حملافظــة ُّ‬\n      ‫أن هذا‬        ‫الصحيح هــو‪َّ :‬‬        ‫يتعـ َّـذر علــى األمانــة حتقيــق الط َّلــب ـ ـ املذكــور ــ‪ .‬و َّ‬\n      ‫يغطــي مســاحة تصــل إلــى س ـ ِّتمائ ٍة و عشــرة آالف (‪)610,000‬‬                                      ‫اإلحيــاء ِّ‬\n      ‫ـرعي رقــم (‪ )103‬يف‬              ‫الشـ ِّ‬  ‫مربـ ٍـع‪ ،‬و قــد امتلكتهــا مبوجــب اإلعــام َّ‬                      ‫متــر َّ‬\n      ‫وم ِّيــز مــن محكمــة ال َّتمييــز بالقــرار رقــم‬                                    ‫‪1408/11/29‬هــ‪ُ ،‬‬\n      ‫(‪ )10/2/1609‬يف ‪1410/05/01‬هــ‪ ،‬بعــد ثبــوت إحيائهــا مــن عــام‬\n      ‫حســب مــا يتضــح مــن‬                  ‫(‪1382‬هــ)‪ ،‬و قبــل صــدور جميــع أوامــر املنــع ـ ـ ْ‬\n      ‫البلديــة إلــى أمانـ ٍة بعشــرين (‪)20‬‬            ‫َّ‬       ‫صــورة اإلعــام املرفــق ــ‪ ،‬و قبــل حتـ ُّـول‬\n      ‫الســامية ا َّلتــي حتججــت بهــا األمانــة صــدر َّأول‬                       ‫أن األوامــر َّ‬     ‫ســنةٍ‪ ،‬كمــا َّ‬\n      ‫واح ــد منهــا برقــم (‪ )19774‬يف ‪1402/08/17‬هــ‪ ،‬بعــد ثبــوت اإلحيــاء و‬\n      ‫وأن املوقــع داخــل‬           ‫ال َّتملــك ألكثــر مــن واحــد و عشــرين (‪ )21‬ســن ًة‪َّ .‬‬\n      ‫«الصويــدرة» كامـ ًـا‪ ،‬حيــث إ َّنهــا تقــع‬                        ‫ُّ‬      ‫ال ِّنطــاق العمرانـ ِّـي حملافظــة‬\n      ‫جنوبــا‪-،‬‬ ‫ً‬               ‫غربــا و شـ ً‬\n                             ‫ـمال و‬                 ‫مخططاتهــا ا َّلتــي تقــع شــرقً ا و ً‬       ‫َّ‬      ‫بكاملهــا بــن‬\n      ‫ـوي ‪ ،-‬و بذلــك ال يتعـ َّـذر علــى األمانــة‬                    ‫حســب مــا ي َّتضــح مــن املصـ َّـور اجلـ ِّ‬     ‫ْ‬\n      ‫الطلــب ـ ـ املذكــور ــ‪ ،‬هــذا جوابــي‪ .‬و بعــرض ذلــك علــى مم ِّثــل‬                                 ‫حتقيــق َّ‬\n      ‫عمــا‬\n          ‫مفصـ ٍـل َّ‬      ‫ـواب َّ‬ ‫املدعيــة‪ ،‬أجــاب بقولــه‪ :‬أطلــب مهلـ ًة؛ إلعــداد جـ ٍ‬                       ‫اجلهــة َّ‬\n              ‫ـدي‪ .‬و يف جلسـ ٍة ُأخــرى لـ َّ‬\n      ‫ـدي أنــا‬                                            ‫املدعــى عليــه‪ ،‬هــذا مــا لـ َّ‬         ‫جــاء يف جــواب َّ‬\n      ‫العامــة يف املدينــة املنـ َّـورة‪ .‬حضــر املتداعيــان‬                   ‫َّ‬        ‫‪ ،...‬القاضــي باحملكمــة‬\n      ‫املدعيــة‪ ،‬هــل أحضــر مــا‬                 ‫أصال ـ ًة و وكال ـ ًة‪ ،‬فجــرى ســؤال مم ِّثــل اجلهــة َّ‬\n      ‫املدعــى‬    ‫عمــا جــاء يف جــواب َّ‬                     ‫وعــد بــه يف جلس ـ ٍة ماضي ـ ٍة مــن ر ٍّد َّ‬\n                                                      ‫مفصـ ٍـل َّ‬\n      ‫صحــة ل ــما‬     ‫الصحيــح مــا ذكر ُتـ ُه يف دعــواي‪ ،‬و ال َّ‬                    ‫عليــه؟ فأجــاب بقولــه‪َّ :‬‬\n      ‫الدعوى‪،‬‬            ‫كـ َـر يف َّ‬    ‫املدعــى عليــه‪ ،‬و ليــس لــدى ممثِّلتــي ســوى ما ُذ ِ‬                ‫ذكــره َّ‬\n\n‫‪505‬‬\n\f‫فو ِج َد‬     ‫امللكيــة ـ ـ املومــأ إليه ـ ـ ُ‬\n                                          ‫َّ‬           ‫ـدي‪ .‬فجــرى االطِّ ــاع علــى إعــام‬           ‫هــذا مــا لـ َّ‬\n‫ـرعية‬\n    ‫الشـ َّ‬       ‫ـف عليــه‪ ،‬و هــو مســتكملٌ لإلجــراءات َّ‬                                ‫مطابقــا ملــا ُع ِطـ َ‬   ‫ً‬\n‫حســب مــا ظهــر لــي مــن مضمــون ضبطــه و ســجلِّه‪،‬‬                                         ‫ظاميــة ـ ـ ْ‬      ‫وال ِّن َّ‬\n‫أن‬‫أيضــا َّ‬    ‫حجــة االســتحكام ــ‪ ،‬كمــا ُو ِجـ َـد ً‬                  ‫ـف َّ‬   ‫ومحتويــات صــورة ملـ ِّ‬\n‫تقدمــت مبعارض ـ ٍة مضمونهــا‪ ،‬هــو مضمــون هــذه‬                                  ‫املدعيــة قــد َّ‬        ‫اجلهــة َّ‬\n‫مت البـ ُّـت يف تلــك املعارضـ ِة بصــرف ال َّنظــر عنهــا‪،‬‬                   ‫الدعــوى بعينهــا‪ ،‬و قــد َّ‬                     ‫َّ‬\n‫املدعيــة علــى ذلــك ا ُحلكــم‪ ،‬و لكــن ُصـ ِّـدق ا ُحلكـ ُـم‬                       ‫و اعترضــت اجلهــة َّ‬\n‫قطعيــا‪ ،‬كمــا جــرى‬           ‫ًّ‬        ‫بصــرف ال َّنظــر مــن محكمــة االســتئناف‪ ،‬و صــار‬\n‫العامــة مبحافظــة‬          ‫َّ‬       ‫االستفســار عــن ســريان مفعولــه مــن احملكمــة‬\n‫«احلناكيــة» باخلطــاب رقــم (‪ )34/1803951‬يف ‪1434/07/25‬هــ‪،‬‬                                                   ‫َّ‬\n‫فوردنــا اجلــواب منهــم باخلطــاب رقــم (‪ )1854‬يف ‪1434/08/02‬هــ‪،‬‬\n‫واملقيــد بأســاس هــذه احملكمــة برقــم (‪ )34/1919686‬يف‬                                                                 ‫َّ‬\n‫«مطابـ ٌـق لســجلِّه‪،‬‬             ‫ـص احلاجــة منــه‪ُ :‬‬     ‫املتضمــن مــا نـ ُّ‬\n                                                                           ‫ِّ‬          ‫‪1434/08/08‬هــ‪ ،‬و‬\n‫ـات»‪.‬‬      ‫وال يوجــد مــا يؤ ِّثــر علــى ســريان مفعولــه‪ ،‬و ال توجــد عليــه مالحظـ ٌ‬\n‫املدعيــة أصال ـ ًة ـ ـ أمانــة منطقــة‬            ‫أن اجلهــة َّ‬     ‫ـاء علــى مــا تقـ َّـدم؛ و مبــا َّ‬               ‫فبنـ ً‬\n‫املدعــى عليــه قــد صــادق‬            ‫أن َّ‬ ‫املدينــة املنـ َّـورة ـ ـ ا َّدعــت مبــا ا َّدعــت بــه‪ ،‬و مبــا َّ‬\n‫مفصــلٌ يف‬      ‫املدعيــة ــ‪ ،‬و دفــع مبــا هــو َّ‬            ‫علــى أصــل دعــوى تلــك اجلهــة ـ ـ َّ‬\n‫بر َّم ِتهــا هــي بعينهــا مــا ســبق أن‬              ‫املدعيــة ُ‬\n                                                                 ‫أن دعــوى اجلهــة َّ‬           ‫جوابــه؛ و مبــا َّ‬\n‫حجــة االســتحكام ـ ـ املنـ َّـوه عنها يف‬                ‫تقدمــت بــه علــى هيئـ ِة معارضـ ٍة علــى َّ‬                      ‫َّ‬\n‫العامــة‬\n      ‫َّ‬              ‫املدعيــة ـ ـ عنــد اســتخراجها لــدى قاضــي احملكمــة‬                             ‫دعــوى َّ‬\n‫أن تلــك املعارضــة قــد ُبـ َّـت فيهــا‬             ‫احلناكيــة ـ ـ إذ ذاك ــ‪ ،‬و مبــا َّ‬‫َّ‬                ‫مبحافظــة‬\n‫مــن جهــة ا ُحلكـ ِـم بصــرف ال َّنظــر عنهــا‪ ،‬و اكتســب ذلــك ا ُحلكــم‬\n‫حجــة‬    ‫أن َّ‬      ‫القطعيــة بتصديــق محكمــة ال َّتمييــز لذلــك ا ُحلكــم؛ و مبــا َّ‬                           ‫َّ‬\n\n                                                                                                                                    ‫‪506‬‬\n\f      ‫ـرعية‬\n          ‫الشـ َّ‬ ‫الدعــوى ـ ـ مســتكمل ٌة لإلجــراءات َّ‬                           ‫االســتحكام ـ ـ محــلَّ َّ‬\n      ‫ـأن اإلحيــاءات ا َّلتــي‬       ‫املدعيــة بـ َّ‬‫أن مــا ذكر ْت ـ ُه اجلهــة َّ‬           ‫ظاميــة؛ و مبــا َّ‬      ‫وال ِّن َّ‬\n      ‫حجــة االســتحكام ال وجــود لهــا اآلن‪ ،‬غيـ ُـر مؤ ِّثـ ٍـر يف أصــل‬                               ‫كـ َـرت يف َّ‬        ‫ُذ ِ‬\n      ‫ـرعيا و ثبــت‬ ‫ـاء شـ ًّ‬  ‫أرضــا إحيـ ً‬    ‫«أن مــن أحيــا ً‬       ‫امللكيــة؛ ل ــما هــو مقـ َّـر ٌر فق ًهــا‪َّ :‬‬  ‫َّ‬\n      ‫يضـ ُّـر بعــد ذلــك صيرورتهــا موا ًتــا مــا دام يعــرف‬                            ‫مت ُّلكــه لهــا‪ ،‬فــا ُ‬\n      ‫(ينظــر‪ :‬فتــاوى ســماحة مفتــي‬                   ‫ـرعا» ُ‬  ‫ـوات لغ ـ ًة ال شـ ً‬   ‫مالِكهــا‪ ،‬فهــي مـ ٌ‬\n      ‫أن القاضــي ممنــو ٌع مــن ال َّنظــر يف‬                 ‫ـعودية ‪)139/8‬؛ و مبــا َّ‬              ‫السـ َّ‬   ‫الديــار ُّ‬       ‫ِّ‬\n      ‫أن االجتهــاد ال ينقــض مبثلــه؛ و جلميــع مــا ســلف‪،‬‬                             ‫قضــاء غيــره؛ و مبــا َّ‬\n      ‫املدعيــة‪ ،‬و ر ِّدهــا‪ ،‬و إخــاء ســبيل‬               ‫فقــد حكمـ ُـت بســقوط دعــوى اجلهــة َّ‬\n      ‫الدعــوى‪ ،‬و بإعــان ا ُحلكــم علــى املتداعيــن‬                             ‫املدعــى عليــه مــن هــذا َّ‬                ‫َّ‬\n      ‫املدعيــة‪ ،‬و طلــب‬     ‫املدعــى عليــه‪ ،‬و لــم يقنــع ُم ِّثــل اجلهــة َّ‬                    ‫وكال ـ ًة‪ ،‬قنــع َّ‬\n      ‫ـتعد بتقــدمي الئح ـ ٍة‬       ‫رفــع ا ُحلكــم إلــى محكمــة االســتئناف‪ ،‬واسـ َّ‬\n      ‫ـتالم نســخ ٍة مــن إعــام‬        ‫ـأن لــه اسـ ُ‬   ‫اعتراضيـةٍ‪ ،‬ف ُأ ِج ْيـ َـب لطلبــه‪ ،‬و ُأفهــم بـ َّ‬       ‫َّ‬\n      ‫ا ُحلكــم يف هــذا اليــوم الثَّالثــاء ‪1434/09/08‬هــ‪ ،‬و أ َّنــه متــى مضــى‬\n      ‫يومــا مــن اليــوم الــذي يلــي هــذا ال َّتاريــخ‪ ،‬و لــم ُيسـلِّم الئحتــه‬                     ‫ثالثــون (‪ً )30‬‬\n      ‫املدعيــة يف طلــب االســتئناف يسـ ُـقط‪،‬‬                        ‫ـإن حـ َّـق اجلهــة َّ‬     ‫االعتراضيــة‪ ،‬فـ َّ‬\n                                                                                                             ‫َّ‬\n      ‫ويلــزم رفــع ا ُحلكــم إلــى محكمــة االســتئناف؛ لتدقيقــه عمـ ًـا باملــا َّدة‬\n      ‫نفيذيــة‪ ،‬ففهــم ذلــك‪،‬‬    ‫َّ‬        ‫ـرعية و لوائحــه ال َّت‬‫الشـ َّ‬  ‫(‪ )179‬مــن نظــام املرافعــات َّ‬\n      ‫و ُحـ ِّـرر يف ‪1434/09/08‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى اهلل و سـلَّم علــى‬\n                                                           ‫محمدٍ و على آله و صحبه أجمعني‪.‬‬                         ‫نبينا َّ‬           ‫ِّ‬\n      ‫أمــا‬ ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬            ‫الصــاة و َّ‬      ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n      ‫املكرمــة‬‫َّ‬       ‫مبكــة‬\n                           ‫بعــد‪ :‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف َّ‬\n      ‫باخلطــاب رقــم (‪ )341278584‬يف ‪1434/11/11‬هــ‪ ،‬و قُ ِّيــدت بأســاس‬\n\n\n‫‪507‬‬\n\f‫مرفقــا بهــا‬\n           ‫ً‬    ‫احملكمــة برقــم (‪ )34/1278584‬يف ‪1434/11/19‬هــ‪،‬‬\n‫الصادر م ِّني برقم (‪ )34314925‬يف ‪1434/09/08‬هـ‪ُ ،‬مظ َّه ًرا‬                      ‫اإلعالم َّ‬\n‫ُقوقيــة الثَّانيــة برقــم (‪ )34349149‬يف‬    ‫الدائــرة احل َّ‬    ‫الصــادر مــن َّ‬\n                                                                              ‫بالقــرار َّ‬\n‫ـص احلاجــة منــه‪« :‬بدراســة احلكــم‪،‬‬      ‫املتضمــن مــا نـ ُّ‬\n                                                         ‫ِّ‬         ‫‪1434/11/04‬هــ‪ ،‬و‬\n‫االعتراضيــة‪ ،‬تقـ َّـرر باألكثريــة املوافقة على‬\n                                        ‫َّ‬                    ‫وصــورة ضبطــه‪ ،‬و الئحتــه‬\n‫ا ُحلكــم» ا‪.‬هــ‪.‬؛ و للبيــان ُحـ ِّـرر يف ‪1434/11/20‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪،‬‬\n   ‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن‪.‬‬    ‫نبينــا َّ‬  ‫وص َّلــى اهلل و س ـلَّم علــى ِّ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باملدينــة املنــورة املكلــف برقــم ‪341278584‬‬\n‫وتاريــخ ‪14334/10/18‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪ ...‬باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34314925‬وتاريــخ‬\n‫‪1434/9/8‬ه ـ ‪ ،‬املتضمــن دعــوى أمانــة املدينة املنورة ضد ‪ ،...‬وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                                     ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                                ‫‪508‬‬\n\f                      ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بتسليم رأس املال‬      ‫شراكة‬\n  ‫‪5‬‬                                                                ‫‪1‬‬\n              ‫واألرباح الناجتة عنه يف التجارة بينهما‬     ‫ومضاربة‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بتعويضه عن‬\n                                                         ‫شراكة‬\n  ‫‪14‬‬     ‫الضرر الذي حصل له من بعض تصرفاته جتاه‬                     ‫‪2‬‬\n                                                         ‫ومضاربة‬\n                  ‫الشراكة واملضاربة بينهما‬\n\n\n         ‫مطالبة املدعي للمدعى عليها برد املبلغ املدفوع‬\n                                                         ‫شراكة‬\n  ‫‪22‬‬     ‫لها للمشاركة واملضاربة وما نتج عنه من أرباح‬               ‫‪3‬‬\n                                                         ‫ومضاربة‬\n                           ‫تخص املدعي‬\n\n\n         ‫مطالبة املدعي للمدعى عليه برد املبلغ املدفوع‬\n         ‫له للمشاركة واملضاربة وما نتج عنه من أرباح‬      ‫شراكة‬\n  ‫‪28‬‬                                                               ‫‪4‬‬\n           ‫تخص املدعي ورد ذلك بسبب ثبوت احلوالة‬          ‫ومضاربة‬\n            ‫لطرف ثالث حيث برئ احمليل من الدين‬\n\n\n         ‫مطالبة املدعي للمدعى عليه برد املبلغ املدفوع‬    ‫شراكة‬\n  ‫‪36‬‬                                                               ‫‪5‬‬\n                    ‫له للمشاركة واملضاربة‬                ‫ومضاربة‬\n\n\n         ‫مطالبة املدعي للمدعى عليه برد املبلغ املدفوع‬    ‫شراكة‬\n  ‫‪43‬‬                                                               ‫‪6‬‬\n                    ‫له للمشاركة واملضاربة‬                ‫ومضاربة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه برد املبلغ املدفوع‬\n         ‫له للمشاركة واملضاربة واعتراض املدعى عليه‬       ‫شراكة‬\n  ‫‪49‬‬                                                               ‫‪7‬‬\n          ‫بأنه طلب منه أن يسلم املبلغ املدعى به لطرف‬     ‫ومضاربة‬\n                          ‫ثالث كمساهمة‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة املدعي للمدعى عليه برد املبلغ املدفوع‬\n         ‫له مع األرباح للمشاركة واملضاربة يف مخطط‬\n                                                          ‫شراكة‬\n  ‫‪58‬‬      ‫عقاري واعتراض املدعى عليه بتأخر تاريخ‬                     ‫‪8‬‬\n                                                          ‫ومضاربة‬\n         ‫دفع املبلغ عن تصفية املساهمة وطعن بالسند‬\n                     ‫املنسوب إليه بأنه مزور‬\n\n\n          ‫مطالبة املدعية للمدعى عليه برد املبلغ املدفوع‬\n                                                          ‫شراكة‬\n  ‫‪68‬‬       ‫له مع األرباح للمشاركة واملضاربة باإلضافة‬                ‫‪9‬‬\n                                                          ‫ومضاربة‬\n             ‫إلى املبلغ الذي قامت املدعية بإقراضه له‬\n\n\n            ‫مطالبة املدعي بإثبات الشراكة بينه وبني‬\n         ‫املدعى عليه ‪،‬وأن يتحمل كال الطرفني اخلسارة‬       ‫شراكة‬\n  ‫‪78‬‬                                                                ‫‪10‬‬\n           ‫املتعلقة بهذه املشاركة ‪،‬وردت الدعوى لعدم‬       ‫ومضاربة‬\n                 ‫االختصاص الوالئي للمحكمة‬\n\n\n          ‫مطالبة املدعي بإفراغ نصيبه من األرض التي‬\n          ‫تشارك بها واملدعى عليه ‪،‬واعترض املدعى‬\n                                                          ‫شراكة‬\n  ‫‪91‬‬       ‫عليه بأن املبالغ املستلمة من املدعي ليست‬                 ‫‪11‬‬\n                                                          ‫ومضاربة‬\n           ‫للمشاركة يف األرض وإمنا الستثمارها يف‬\n                     ‫املساهمات العقارية‬\n\n\n           ‫مطالبة املدعي للمدعى عليه برد املبلغ الذي‬\n          ‫قام بدفعه ملكفوله للشراكة بأعمال جتارية‬\n             ‫لكونه عرض عليه الشراكة التجارية‬              ‫شراكة‬\n ‫‪108‬‬                                                                ‫‪12‬‬\n          ‫كمندوب لكفيله واعتراض املدعى عليه بأن‬           ‫ومضاربة‬\n         ‫األموال محالة ملكفوله وليست له وأنه ال عال